// Collects everything the morning brief needs. Swap these
// arrays for real sources (DB, API, calendar) when you wire it up.
const now = new Date();
const dayOfYear = Math.floor((now - new Date(now.getFullYear(), 0, 0)) / 86400000);
const backlog = [
  'Ship the webhook retry backoff',
  'Review DAG engine error routing',
  'Draft the Q4 automation report',
  'Triage failed executions from yesterday',
  'Document the SMTP credential setup',
];

return [{
  json: {
    to: 'team@flowops.dev',
    dateLabel: now.toLocaleDateString('en-GB', {
      weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
    }),
    highlights: [
      `${3 + (dayOfYear % 4)} workflows ran overnight`,
      `${1 + (dayOfYear % 3)} execution(s) need a second look`,
      'Next maintenance window: Friday 18:00',
    ],
    focus: [backlog[dayOfYear % backlog.length], backlog[(dayOfYear + 2) % backlog.length]],
    metrics: {
      'Runs today': 12 + (dayOfYear % 9),
      'Success rate': '98.4%',
      'Queue depth': 0,
    },
  },
}];

// Turns the drafted markdown into a ready-to-send html email.
const text = String($input.first().json.text ?? '');
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const blocks = [];
let list = null;
const closeList = () => {
  if (list) { blocks.push('</' + list + '>'); list = null; }
};
const openList = (kind, style) => {
  if (list === kind) return;
  closeList();
  blocks.push('<' + kind + ' style="' + style + '">');
  list = kind;
};

for (const raw of text.split('\n')) {
  const line = raw.trim();
  if (!line) { closeList(); continue; }

  if (/^#{2,3}\s+/.test(line)) {
    closeList();
    const title = esc(line.replace(/^#{2,3}\s+/, ''));
    blocks.push('<h3 style="margin:24px 0 8px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:#FF6D5A">' + title + '</h3>');
    continue;
  }
  if (/^[-*]\s+/.test(line)) {
    openList('ul', 'margin:0 0 16px 20px;padding:0');
    blocks.push('<li style="margin:6px 0">' + esc(line.replace(/^[-*]\s+/, '')) + '</li>');
    continue;
  }
  const numbered = /^(\d+)\.\s+(.*)$/.exec(line);
  if (numbered) {
    openList('ol', 'margin:0 0 16px 20px;padding:0');
    blocks.push('<li style="margin:6px 0">' + esc(numbered[2]) + '</li>');
    continue;
  }
  closeList();
  blocks.push('<p style="margin:0 0 12px">' + esc(line) + '</p>');
}
closeList();

const html = '<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#18191C;max-width:560px">' + blocks.join('') + '</div>';

return [{
  json: {
    to: 'team@flowops.dev',
    subject: 'Morning brief — ' + new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }),
    html,
    text,
  },
}];
